//! Arbitrary-precision decimal arithmetic.
//!
//! A `Decimal` is stored as a sign, a little-endian vector of base-10 digits
//! (the magnitude), and a `scale`: the number of digits that belong to the
//! fractional part. For example, `-1.230` is stored as
//! `{ negative: true, digits: [0, 3, 2, 1], scale: 3 }`.
//! Values are normalized: trailing fractional zeros are stripped and zero is
//! always stored as positive.

use std::cmp::Ordering;
use std::ops::{Add, Mul, Sub};

/// Type implementing arbitrary-precision decimal arithmetic
#[derive(Clone, Debug)]
pub struct Decimal {
    negative: bool,
    /// Magnitude digits, least-significant first, each in 0..=9.
    digits: Vec<u8>,
    /// Number of digits after the decimal point.
    scale: usize,
}

impl Decimal {
    pub fn try_from(input: &str) -> Option<Decimal> {
        let input = input.trim();
        let (negative, rest) = match input.strip_prefix('-') {
            Some(r) => (true, r),
            None => (false, input.strip_prefix('+').unwrap_or(input)),
        };

        let mut parts = rest.split('.');
        let int_part = parts.next().unwrap_or("");
        let frac_part = match parts.next() {
            Some(f) => {
                if parts.next().is_some() {
                    return None; // more than one '.'
                }
                f
            }
            None => "",
        };

        if !int_part.is_ascii() || !frac_part.is_ascii() {
            return None;
        }
        let int_digits: Vec<u8> = int_part
            .chars()
            .map(|c| c.is_ascii_digit().then(|| c as u8 - b'0'))
            .collect::<Option<Vec<_>>>()?;
        let frac_digits: Vec<u8> = frac_part
            .chars()
            .map(|c| c.is_ascii_digit().then(|| c as u8 - b'0'))
            .collect::<Option<Vec<_>>>()?;

        if int_digits.is_empty() && frac_digits.is_empty() {
            return None; // empty string, "-", ".", etc.
        }

        // Store magnitude little-endian: fractional digits reversed first,
        // then integer digits reversed.
        let mut digits: Vec<u8> = frac_digits.iter().rev().copied().collect();
        digits.extend(int_digits.iter().rev().copied());

        let mut d = Decimal {
            negative,
            digits,
            scale: frac_digits.len(),
        };
        d.normalize();
        Some(d)
    }

    /// Strip leading (most-significant) and trailing (least-significant,
    /// fractional) zero digits; canonicalize zero to positive.
    fn normalize(&mut self) {
        while self.digits.len() > self.scale && *self.digits.last().unwrap() == 0 {
            self.digits.pop();
        }
        while self.scale > 0 && self.digits.first() == Some(&0) {
            self.digits.remove(0);
            self.scale -= 1;
        }
        if self.digits.iter().all(|&d| d == 0) {
            self.digits.clear();
            self.scale = 0;
            self.negative = false;
        }
    }

    fn is_zero(&self) -> bool {
        self.digits.is_empty()
    }

    /// Bring both values to a common scale by padding the smaller one.
    fn aligned(&self, other: &Decimal) -> (Vec<u8>, Vec<u8>, usize) {
        let scale = self.scale.max(other.scale);
        let mut a = self.digits.clone();
        let mut b = other.digits.clone();
        a.resize(scale - self.scale + a.len().max(self.scale), 0);
        b.resize(scale - other.scale + b.len().max(other.scale), 0);
        // ensure lengths are at least `scale` and equal for comparison
        let len = a.len().max(b.len()).max(scale);
        a.resize(len, 0);
        b.resize(len, 0);
        (a, b, scale)
    }

    /// Compare magnitudes of `self` and `other` (ignoring signs).
    fn cmp_mag(&self, other: &Decimal) -> Ordering {
        let (a, b, _) = self.aligned(other);
        for i in (0..a.len()).rev() {
            match a[i].cmp(&b[i]) {
                Ordering::Equal => continue,
                o => return o,
            }
        }
        Ordering::Equal
    }

    /// Add magnitudes, returning little-endian digits at the given scale.
    fn add_mag(a: &[u8], b: &[u8], scale: usize) -> Vec<u8> {
        let len = a.len().max(b.len());
        let mut out = Vec::with_capacity(len + 1);
        let mut carry = 0u8;
        for i in 0..len {
            let x = a.get(i).copied().unwrap_or(0);
            let y = b.get(i).copied().unwrap_or(0);
            let s = x + y + carry;
            out.push(s % 10);
            carry = s / 10;
        }
        if carry > 0 {
            out.push(carry);
        }
        let _ = scale;
        out
    }

    /// Subtract magnitudes, requiring a >= b.
    fn sub_mag(a: &[u8], b: &[u8]) -> Vec<u8> {
        let mut out = Vec::with_capacity(a.len());
        let mut borrow = 0i8;
        for i in 0..a.len() {
            let x = a[i] as i8;
            let y = b.get(i).copied().unwrap_or(0) as i8;
            let mut d = x - y - borrow;
            borrow = 0;
            if d < 0 {
                d += 10;
                borrow = 1;
            }
            out.push(d as u8);
        }
        out
    }

    fn from_parts(negative: bool, digits: Vec<u8>, scale: usize) -> Decimal {
        let mut d = Decimal {
            negative,
            digits,
            scale,
        };
        d.normalize();
        d
    }
}

impl PartialEq for Decimal {
    fn eq(&self, other: &Decimal) -> bool {
        // Values are normalized, so zero is only ever represented once.
        self.negative == other.negative && self.cmp_mag(other) == Ordering::Equal
    }
}

impl Eq for Decimal {}

impl PartialOrd for Decimal {
    fn partial_cmp(&self, other: &Decimal) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Decimal {
    fn cmp(&self, other: &Decimal) -> Ordering {
        match (self.negative, other.negative) {
            (false, true) => {
                if self.is_zero() && other.is_zero() {
                    Ordering::Equal
                } else {
                    Ordering::Greater
                }
            }
            (true, false) => {
                if self.is_zero() && other.is_zero() {
                    Ordering::Equal
                } else {
                    Ordering::Less
                }
            }
            (false, false) => self.cmp_mag(other),
            (true, true) => other.cmp_mag(self).reverse(),
        }
    }
}

impl Add for Decimal {
    type Output = Decimal;

    fn add(self, other: Decimal) -> Decimal {
        let (a, b, scale) = self.aligned(&other);
        if self.negative == other.negative {
            Decimal::from_parts(self.negative, Decimal::add_mag(&a, &b, scale), scale)
        } else {
            match Decimal::cmp_mag(&self, &other) {
                Ordering::Greater => Decimal::from_parts(self.negative, Decimal::sub_mag(&a, &b), scale),
                Ordering::Less => Decimal::from_parts(other.negative, Decimal::sub_mag(&b, &a)),
                Ordering::Equal => Decimal::from_parts(false, vec![], scale),
            }
        }
    }
}

impl Sub for Decimal {
    type Output = Decimal;

    fn sub(self, other: Decimal) -> Decimal {
        self + other.negated()
    }
}

impl Mul for Decimal {
    type Output = Decimal;

    fn mul(self, other: Decimal) -> Decimal {
        let mut out = vec![0u8; self.digits.len() + other.digits.len()];
        for (i, &x) in self.digits.iter().enumerate() {
            let mut carry = 0u16;
            for (j, &y) in other.digits.iter().enumerate() {
                let s = out[i + j] as u16 + (x as u16) * (y as u16) + carry;
                out[i + j] = (s % 10) as u8;
                carry = s / 10;
            }
            let mut k = i + other.digits.len();
            while carry > 0 {
                let s = out[k] as u16 + carry;
                out[k] = (s % 10) as u8;
                carry = s / 10;
                k += 1;
            }
        }
        let negative = self.negative != other.negative;
        let scale = self.scale + other.scale;
        Decimal::from_parts(negative, out, scale)
    }
}

impl Decimal {
    fn negated(mut self) -> Decimal {
        if !self.is_zero() {
            self.negative = !self.negative;
        }
        self
    }
}

