/// Bring both values to a common scale by zero-padding the fractional
/// (low) end of the value with the smaller scale.
fn aligned(&self, other: &Decimal) -> (Vec<u8>, Vec<u8>, usize) {
    let scale = self.scale.max(other.scale);
    let mut a = vec![0u8; scale - self.scale];
    a.extend_from_slice(&self.digits);
    let mut b = vec![0u8; scale - other.scale];
    b.extend_from_slice(&other.digits);
    // equalize lengths (high end) for uniform indexing
    let len = a.len().max(b.len());
    a.resize(len, 0);
    b.resize(len, 0);
    (a, b, scale)
}

